                                    toField: Number(b?.fieldValue),
                                    deltaFirstMeridional: d1,
                                    deltaSecondMeridional: d2,
                                    modeFrom: String(a?.effectivePupilSamplingMode || ''),
                                    modeTo: String(b?.effectivePupilSamplingMode || ''),
